    "breadcrumb": "AWS Workshop Report \u003e Workshop",
    "content": "Module 1: Storage \u0026 Database\rSet up the DynamoDB single-table for generic data storage and an S3 bucket for storing application assets.\nCreate lib/storage-stack.ts:\nimport * as cdk from 'aws-cdk-lib'; import * as dynamodb from 'aws-cdk-lib/aws-dynamodb'; import * as s3 from 'aws-cdk-lib/aws-s3'; import { Construct } from 'constructs'; export class StorageStack extends cdk.Stack { public readonly table: dynamodb.Table; public readonly assetBucket: s3.Bucket; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); // Initialize DynamoDB Single Table for generic entity metadata this.table = new dynamodb.Table(this, 'AppSingleTable', { partitionKey: { name: 'PK', type: dynamodb.AttributeType.STRING }, sortKey: { name: 'SK', type: dynamodb.AttributeType.STRING }, billingMode: dynamodb.BillingMode.PAY_PER_REQUEST, // On-Demand pricing pointInTimeRecovery: true, // Enables automated backups removalPolicy: cdk.RemovalPolicy.DESTROY, // Dev environment cleanup }); // Create private S3 Bucket for application assets this.assetBucket = new s3.Bucket(this, 'AssetStorageBucket', { encryption: s3.BucketEncryption.S3_MANAGED, blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL, // Secure private bucket removalPolicy: cdk.RemovalPolicy.DESTROY, autoDeleteObjects: true, }); } }",
    "description": "Module 1: Storage \u0026 Database\rSet up the DynamoDB single-table for generic data storage and an S3 bucket for storing application assets.\nCreate lib/storage-stack.ts:\nimport * as cdk from 'aws-cdk-lib'; import * as dynamodb from 'aws-cdk-lib/aws-dynamodb'; import * as s3 from 'aws-cdk-lib/aws-s3'; import { Construct } from 'constructs'; export class StorageStack extends cdk.Stack { public readonly table: dynamodb.Table; public readonly assetBucket: s3.Bucket; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); // Initialize DynamoDB Single Table for generic entity metadata this.table = new dynamodb.Table(this, 'AppSingleTable', { partitionKey: { name: 'PK', type: dynamodb.AttributeType.STRING }, sortKey: { name: 'SK', type: dynamodb.AttributeType.STRING }, billingMode: dynamodb.BillingMode.PAY_PER_REQUEST, // On-Demand pricing pointInTimeRecovery: true, // Enables automated backups removalPolicy: cdk.RemovalPolicy.DESTROY, // Dev environment cleanup }); // Create private S3 Bucket for application assets this.assetBucket = new s3.Bucket(this, 'AssetStorageBucket', { encryption: s3.BucketEncryption.S3_MANAGED, blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL, // Secure private bucket removalPolicy: cdk.RemovalPolicy.DESTROY, autoDeleteObjects: true, }); } }",
    "tags": [],
    "title": "Module 1: Storage \u0026 Database",
    "uri": "/en/5-workshop/5.3-module1-storage/index.html"
